import json

_BANK = "/home/ubuntu/Shine_Academy_Naroda/app_core/content/cbse/class10/maths/ncert_rationalised/ch02_polynomials/questions.json"

def _graph_feedback(options, correct, lang):
    count = int(options[correct].strip("$"))
    out = []
    for i, o in enumerate(options):
        n = int(o.strip("$"))
        if lang == "hi":
            if i == correct:
                out.append(f"सही! वक्र x-अक्ष से {count} बिंदु{'ओं' if count != 1 else ''} पर मिलता है, अतः {count} शून्यक {'हैं' if count != 1 else 'है'}।" if count else "सही! वक्र x-अक्ष से कभी नहीं मिलता, अतः कोई शून्यक नहीं है।")
            elif count == 0:
                out.append("ध्यान से देखिए: आलेख x-अक्ष को कभी नहीं छूता, अतः कोई शून्यक नहीं है।")
            else:
                out.append(f"केवल उन बिंदुओं को फिर से गिनिए जहाँ वक्र x-अक्ष से मिलता है: वे {count} हैं, {n} नहीं।")
        else:
            if i == correct:
                out.append(f"સાચું! વક્ર x-અક્ષને {count} બિંદુએ મળે છે, તેથી {count} શૂન્ય છે." if count else "સાચું! વક્ર x-અક્ષને ક્યારેય મળતો નથી, તેથી એક પણ શૂન્ય નથી.")
            elif count == 0:
                out.append("ધ્યાનથી જુઓ: આલેખ x-અક્ષને ક્યારેય સ્પર્શતો નથી, તેથી એક પણ શૂન્ય નથી.")
            else:
                out.append(f"ફક્ત એ બિંદુઓ ફરી ગણો જ્યાં વક્ર x-અક્ષને મળે છે: તે {count} છે, {n} નહીં.")
    return out

Q = {}
for _q in json.load(open(_BANK, encoding="utf-8"))["questions"]:
    if _q["id"].startswith("ch02.q.ex2_1"):
        part = _q["id"].rsplit(".", 1)[1]
        Q[f"{_q['id']}.option_feedback"] = (_graph_feedback(_q["options"], _q["correct_index"], "hi"), _graph_feedback(_q["options"], _q["correct_index"], "gu"))
        Q[f"{_q['id']}.figure.title"] = (f"भाग ({part}) का आलेख", f"ભાગ ({part}) નો આલેખ")
        if _q["explanation"]:
            c = _q["correct_index"]
            Q[f"{_q['id']}.explanation"] = (
                f"आलेख x-अक्ष से {c} बिंदुओं पर मिलता है, अतः $p(x)$ के {c} शून्यक हैं।" if c != 1 else "आलेख x-अक्ष से 1 बिंदु पर मिलता है, अतः $p(x)$ का 1 शून्यक है।",
                f"આલેખ x-અક્ષને {c} બિંદુએ મળે છે, તેથી $p(x)$ નાં {c} શૂન્યો છે." if c != 1 else "આલેખ x-અક્ષને 1 બિંદુએ મળે છે, તેથી $p(x)$ નું 1 શૂન્ય છે.")

